{
  "summary": "For a $100,000 Apple Music payment, the best documented business-card option depends on how Apple submits the transaction. Rewards are based on the merchant category code, not simply the service description.",
  "options": [
    {
      "card": "Business Platinum Rewards Card",
      "likely_return": "1.5% if Apple Music is treated as a non-qualifying purchase",
      "estimated_cash_back": "$1,500",
      "potential_maximum": "4.0% ($4,000) only if the charge is coded as qualifying media, software, or travel",
      "important_limit": "The documented 4.0% media benefit is for advertising and media placements, such as streaming ads—not ordinary streaming subscriptions. The card's credit-limit and annual-fee terms were not available in the retrieved information."
    },
    {
      "card": "Business Gold Rewards Card",
      "likely_return": "1.0% if Apple Music is treated as entertainment or another non-operations purchase",
      "estimated_cash_back": "$1,000",
      "potential_maximum": "2.5% ($2,500) only if the transaction is coded as qualifying operations spend",
      "terms": {
        "annual_fee": "$200",
        "apr_on_carried_balances": "17.99%",
        "typical_credit_limit": "$37,500-$225,000",
        "eligibility": "Minimum personal credit score of 735 and business PAYDEX score of 67"
      },
      "important_limit": "The operations guidance specifically says entertainment-coded transactions do not qualify for the 2.5% rate."
    },
    {
      "card": "Business Silver Rewards Card",
      "likely_return": "1.0% ($1,000)",
      "terms": {
        "annual_fee": "$0",
        "typical_credit_limit": "$10,000-$100,000"
      },
      "important_limit": "Apple is specifically listed as an exclusion from the 10.0% bonus rate, so an Apple-billed Apple Music charge would earn the standard 1.0% rate. A $100,000 payment would also be at the top of the documented typical credit-limit range and remains subject to approval."
    },
    {
      "card": "Business Bronze Rewards Card",
      "likely_return": "1.0% ($1,000)",
      "potential_bonus": "A documented new-customer offer provides a $500 statement credit after $10,000 of spending in the first two months, but the retrieved terms do not establish that this offer is currently available.",
      "terms": {
        "annual_fee": "$0",
        "minimum_starting_credit_line": "$10,000",
        "eligibility": "Minimum personal FICO score of 660"
      }
    }
  ],
  "recommendation": "Do not assume that Apple Music qualifies for a bonus category. Based on the available terms, Business Platinum could be strongest if Apple confirms that the charge will be coded as qualifying media or software; otherwise its documented fallback rate of 1.5% would produce approximately $1,500. Business Gold would generally produce about $1,000 unless the charge is coded as qualifying operations. Business Silver is not a strong choice for this purchase because Apple is explicitly excluded from its 10.0% bonus.",
  "before_applying": [
    "Confirm the expected merchant category code directly with Apple or by checking a small posted test transaction, because rewards depend on coding.",
    "Confirm the approved credit line is sufficient for the single $100,000 charge; approval and credit limits are not guaranteed.",
    "Pay the statement in full if possible. Carrying $100,000 at the documented APRs could quickly outweigh the rewards."
  ],
  "calculation_basis": {
    "one_percent": "$1,000",
    "one_point_five_percent": "$1,500",
    "two_point_five_percent": "$2,500",
    "four_percent": "$4,000"
  }
}

{
  "recommendation": "Apply for the Business Platinum Rewards Card, provided you are approved for a credit line of at least $100,000 and its annual fee is acceptable to you.",
  "realistic_return": {
    "conservative_expectation": "Approximately $1,500 cash back, using the 1.5% rate for purchases that do not qualify for an enhanced category.",
    "upside_if_coded_as_qualifying_media": "Up to approximately $4,000 cash back at 4.0%.",
    "expected_range": "$1,500-$4,000",
    "net_return": "The net amount is the cash back minus any Business Platinum annual fee. The annual fee was not specified in the available product terms, so I cannot calculate that net figure."
  },
  "why_this_is_the_best_choice": [
    "Business Silver is not suitable for this purchase because Apple is specifically excluded from its 10.0% bonus and would earn 1.0%, or about $1,000.",
    "Business Gold earns 2.5% only for qualifying operations spend, while entertainment-coded transactions do not qualify; Apple Music could therefore earn only 1.0%, or about $1,000.",
    "Business Platinum has the strongest documented fallback rate at 1.5% and the highest documented upside if the charge is submitted under a qualifying media category."
  ],
  "coding_caveat": "Do not assume that an Apple Music subscription will receive the 4.0% media rate. The documented qualifying media examples focus on advertising and media placements, while an ordinary streaming subscription may be coded as entertainment or another non-qualifying category.",
  "important_conditions": [
    "Rewards depend on the merchant category code assigned by Apple's payment processor.",
    "Approval and the required $100,000 credit line are not guaranteed.",
    "Pay the statement in full if possible; interest on a carried balance could exceed the rewards quickly."
  ]
}
